var p = Math.max(1, Number(page || 1));
var primary = String(basicUrl || "https://skrbtso.top").replace(/\/+$/, "");
var bases = [primary, "https://skrbtlz.top"];
var seenBase = {};
var cleanBases = [];
for (var bi = 0; bi < bases.length; bi++) {
    var bb = String(bases[bi] || "").replace(/\/+$/, "");
    if (bb && !seenBase[bb]) { seenBase[bb] = 1; cleanBases.push(bb); }
}

function cleanText(v) {
    return String(v || "")
        .replace(/<script[\s\S]*?<\/script>/gi, "")
        .replace(/<style[\s\S]*?<\/style>/gi, "")
        .replace(/<[^>]+>/g, "")
        .replace(/&nbsp;/gi, " " )
        .replace(/&amp;/gi, "&")
        .replace(/&lt;/gi, "<")
        .replace(/&gt;/gi, ">")
        .replace(/&#39;/gi, "'")
        .replace(/&quot;/gi, "\"")
        .replace(/&#(\d+);/g, function(_, n){ try { return String.fromCharCode(Number(n)); } catch(e) { return _; } })
        .replace(/\s+/g, " " )
        .trim();
}
function sizeToBytes(text) {
    var m = cleanText(text).match(/([0-9.]+)\s*(TB|GB|MB|KB|B)/i);
    if (!m) return 0;
    var n = Number(m[1] || 0);
    var u = String(m[2] || "B").toUpperCase();
    var pow = {B:0,KB:1,MB:2,GB:3,TB:4}[u] || 0;
    return Math.round(n * Math.pow(1024, pow));
}
function attr(tag, name) {
    var re = new RegExp(name + "\\s*=\\s*[\"']([^\"']*)[\"']", "i");
    var m = String(tag || "").match(re);
    return m ? m[1] : "";
}
function findCommonLink(block) {
    var tags = String(block || "").match(/<a\b[^>]*>[\s\S]*?<\/a>/gi) || [];
    for (var i = 0; i < tags.length; i++) {
        var open = (tags[i].match(/^<a\b[^>]*>/i) || [""])[0];
        var cls = attr(open, "class");
        if (/(^|\s)common-link(\s|$)/.test(cls)) {
            return { href: attr(open, "href"), title: cleanText(tags[i]) };
        }
    }
    return null;
}
function requestSearch(base) {
    var url = base + "/search?keyword=" + encodeURIComponent(String(s || ""));
    if (p > 1) url += "&p=" + p;
    var ua = "Mozilla/5.0 (Linux; Android 16) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0 Mobile Safari/537.36";
    var text = fetch(url, {
        headers: {
            "User-Agent": ua,
            "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
            "Accept-Language": "zh-CN,zh;q=0.9,en;q=0.6",
            "Referer": base + "/"
        },
        timeout: 12000
    });
    return { base: base, url: url, text: String(text || "") };
}

var response = null;
var errors = [];
for (var b = 0; b < cleanBases.length; b++) {
    try {
        var r = requestSearch(cleanBases[b]);
        if (/recaptcha\/v4\/challenge|anti\/recaptcha|\/challenge/i.test(r.text)) {
            errors.push(cleanBases[b] + " 触发网页验证");
            continue;
        }
        if (r.text.indexOf("list-unstyled") >= 0 || r.text.indexOf("rrt common-link") >= 0 || r.text.indexOf("common-link") >= 0) {
            response = r;
            break;
        }
        if (/403 Forbidden|Access Denied|Cloudflare|captcha/i.test(r.text)) {
            errors.push(cleanBases[b] + " 被风控/拦截");
        } else {
            errors.push(cleanBases[b] + " 未识别到结果列表");
        }
    } catch (e) {
        errors.push(cleanBases[b] + "：" + (e.message || e));
    }
}
if (!response) {
    throw new Error("SkrBT 搜索失败；" + errors.join("；") + "。若提示网页验证，请先在海阔网页中打开 SkrBT 完成验证后再重试");
}

var html = response.text;
var blocks = html.match(/<(?:ul|div)\b[^>]*class=["'][^"']*list-unstyled[^"']*["'][^>]*>[\s\S]*?<\/(?:ul|div)>/gi) || [];
var out = [];
for (var i = 0; i < blocks.length; i++) {
    var block = blocks[i];
    var link = findCommonLink(block);
    if (!link || !link.href || !link.title) continue;
    if (/^https?:\/\//i.test(link.href) && link.href.indexOf(response.base) !== 0) continue;
    var detailUrl = /^https?:\/\//i.test(link.href) ? link.href : response.base + (link.href.charAt(0) === "/" ? link.href : "/" + link.href);

    var li = block.match(/<li\b[^>]*class=["'][^"']*rrmi[^"']*["'][^>]*>[\s\S]*?<\/li>/i);
    var spans = li ? (li[0].match(/<span\b[^>]*>[\s\S]*?<\/span>/gi) || []) : [];
    var sizeText = spans.length > 1 ? cleanText(spans[1]) : "";
    var countText = spans.length > 2 ? cleanText(spans[2]) : "";
    var dateText = spans.length > 3 ? cleanText(spans[3]) : "";
    var countMatch = countText.match(/(\d+)/);
    var dateMatch = dateText.match(/(20\d{2}[-\/.]\d{1,2}[-\/.]\d{1,2}(?:\s+\d{1,2}:\d{1,2}(?::\d{1,2})?)?)/);
    var desc = [];
    if (sizeText) desc.push(sizeText);
    if (countMatch) desc.push("文件 " + countMatch[1]);

    out.push({
        title: link.title,
        url: detailUrl,
        bytes: sizeToBytes(sizeText),
        seeders: -1,
        peers: -1,
        date: dateMatch ? dateMatch[1] : dateText,
        desc: desc.join(" · " )
    });
}
if (!out.length && /没有|暂无|无结果|not found|no result/i.test(cleanText(html))) return [];
if (!out.length) throw new Error("SkrBT 页面已打开，但结果 DOM 结构可能已变化");
return out;

findAliUrl:
var url = String(input || "").trim();
if (!url) return "";
var m = url.match(/^(https?:\/\/[^\/]+)/i);
var base = m ? m[1] : String(basicUrl || "https://skrbtso.top").replace(/\/+$/, "");
var ua = "Mozilla/5.0 (Linux; Android 16) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0 Mobile Safari/537.36";
var html = fetch(url, {
    headers: {
        "User-Agent": ua,
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
        "Accept-Language": "zh-CN,zh;q=0.9,en;q=0.6",
        "Referer": base + "/search"
    },
    timeout: 12000
});
html = String(html || "");
if (/recaptcha\/v4\/challenge|anti\/recaptcha|\/challenge/i.test(html)) {
    throw new Error("SkrBT 详情页触发网页验证，请先在海阔网页中完成验证");
}
var tag = "";
var tags = html.match(/<a\b[^>]*>[\s\S]*?<\/a>/gi) || [];
for (var i = 0; i < tags.length; i++) {
    var open = (tags[i].match(/^<a\b[^>]*>/i) || [""])[0];
    if (/\bid\s*=\s*["']magnet["']/i.test(open)) { tag = open; break; }
}
if (!tag) {
    var direct = html.match(/magnet:\?xt=urn:btih:[A-Za-z0-9]{32,40}(?:&amp;[^"'<> ]+|&[^"'<> ]+)*/i);
    if (direct) return String(direct[0]).replace(/&amp;/g, "&");
    throw new Error("SkrBT 详情页未找到 #magnet");
}
var hm = tag.match(/\bhref\s*=\s*["']([^"']+)["']/i);
if (!hm) throw new Error("SkrBT #magnet 缺少 href");
return String(hm[1] || "").replace(/&amp;/g, "&");
